def is_hill_number(n):
    s = str(n)
    rise = False
    fall = False
    for i in range(1, len(s)):
        if s[i] > s[i - 1]:
            if fall:
                return False
            rise = True
        elif s[i] < s[i - 1]:
            fall = True
        else:
            continue
    return True

def count_hill_numbers(n):
    count = 0
    for i in range(1, n + 1):
        if is_hill_number(i):
            count += 1
    return count

def main():
    n = int(input().strip())
    if is_hill_number(n):
        print(count_hill_numbers(n))
    else:
        print(-1)

if __name__ == "__main__":
    main()
